<template>
  <div class="login-page">
    <el-card class="login-card" shadow="always">
      <template #header>
        <div class="login-header">
          <el-icon :size="36" color="var(--el-color-primary)"><lightning /></el-icon>
          <h1>ChaosOps</h1>
          <p>{{ t('login.subtitle') }}</p>
        </div>
      </template>

      <el-form :model="form" :rules="rules" ref="formRef" @keyup.enter="handleLogin">
        <el-form-item prop="username">
          <el-input
            v-model="form.username"
            :placeholder="t('login.usernamePlaceholder')"
            :prefix-icon="User"
            size="large"
          />
        </el-form-item>
        <el-form-item prop="password">
          <el-input
            v-model="form.password"
            type="password"
            :placeholder="t('login.passwordPlaceholder')"
            :prefix-icon="Lock"
            size="large"
            show-password
          />
        </el-form-item>
        <el-form-item>
          <el-button
            type="primary"
            size="large"
            :loading="loading"
            @click="handleLogin"
            style="width: 100%"
          >
            {{ t('login.submit') }}
          </el-button>
        </el-form-item>
      </el-form>

      <div v-if="errorMessage" class="login-error">
        <el-alert :title="errorMessage" type="error" show-icon :closable="false" />
      </div>

      <div class="login-actions">
        <router-link to="/auth/forgot-password">{{ t('login.forgot') }}</router-link>
      </div>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import type { FormInstance, FormRules } from 'element-plus'
import { ElMessage } from 'element-plus'
import { User, Lock } from '@element-plus/icons-vue'
import { login, getMe } from '@/api/auth'
import { useAuthStore } from '@/stores/auth'
import { extractErrorMessage } from '@/utils/error'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()
const router = useRouter()
const authStore = useAuthStore()

const form = reactive({
  username: '',
  password: '',
})

const loading = ref(false)
const errorMessage = ref('')
const formRef = ref<FormInstance>()

// 校验提示用函数延迟取值，保证切换语言后重新校验时提示跟着变
const rules: FormRules = {
  username: [
    { required: true, message: () => t('login.usernameRequired'), trigger: 'blur' },
  ],
  password: [
    { required: true, message: () => t('login.passwordRequired'), trigger: 'blur' },
  ],
}

async function handleLogin() {
  if (!formRef.value) return

  try {
    await formRef.value.validate()
  } catch {
    return
  }

  loading.value = true
  errorMessage.value = ''

  try {
    await login(form.username, form.password)

    const user = await getMe()
    authStore.setUser(user)

    ElMessage.success(t('login.success'))
    router.push('/')
  } catch (error: any) {
    errorMessage.value = extractErrorMessage(error, t('login.failed'))
  } finally {
    loading.value = false
  }
}
</script>

